using Repricing.Execution;
using Repricing.Storage;
namespace Repricing.Tests;
public class DiscountBaseTests
{
 static PriceInput Input()=>new("123","MLB","BRL","SKU-A",null,null,null,18.9m,null,false,false,null);
 static ZiniaoProduct Product(decimal b=169,bool active=true,decimal price=33.79m)=>new("456","SKU-A","商品",$"R$ {b:0.00}".Replace('.',','),[new("C-1","普通活动",active?"激活":"",$"R$ {(active?price:b*.95m):0.00}".Replace('.',','),active,true,false,!active)]);
 sealed class Client:IZiniaoPriceCutClient
 {
  public List<string> Calls=[];public ZiniaoProduct Current=Product();public bool ExitDisconnect,BaseDisconnect,JoinDisconnect,NoOffer,ChangeBaseUnexpected,Verification,UnderReviewAfterBase,UnderReviewAfterJoin;
  public Task<ZiniaoStore[]> StoresAsync(CancellationToken ct)=>Task.FromResult(new[]{new ZiniaoStore("123","测试","MercadoLibre-巴西")});
  public Task<ZiniaoProduct[]> ReadAsync(ZiniaoStore s,PriceInput i,CancellationToken ct){Calls.Add("read");return Task.FromResult(new[]{Current});}
  public Task PrepareExitAsync(PriceCutPlan p,CancellationToken ct){Calls.Add("prepare-exit");return Task.CompletedTask;}
  public Task ConfirmExitAsync(PriceCutPlan p,CancellationToken ct){Calls.Add("exit");Current=Product(active:false);if(ExitDisconnect)throw new IOException();return Task.CompletedTask;}
  public Task PrepareBaseAsync(PriceCutPlan p,CancellationToken ct){Calls.Add("prepare-base");if(Verification)throw new VerificationRequiredException();return Task.CompletedTask;}
  public Task SubmitBaseAsync(PriceCutPlan p,CancellationToken ct){Calls.Add("save-base");Current=Product(ChangeBaseUnexpected?80:p.DiscountBase!.Value,false);if(NoOffer)Current=Current with{Promotions=[]};if(UnderReviewAfterBase)Current=Current with{ListingStatus="需审核未激活"};if(BaseDisconnect)throw new IOException();return Task.CompletedTask;}
  public Task PrepareAsync(PriceCutPlan p,CancellationToken ct){Calls.Add("prepare-join");Assert.True(p.Join);Assert.False(p.ChangeBase);Assert.Equal(75.6m,p.BasePrice);Assert.Equal(18.9m,p.Input.TargetPrice);return Task.CompletedTask;}
  public Task SubmitAsync(PriceCutPlan p,CancellationToken ct){Calls.Add("join");Current=Product(75.6m,true,18.9m);if(UnderReviewAfterJoin)Current=Current with{ListingStatus="需审核未激活"};if(JoinDisconnect)throw new IOException();return Task.CompletedTask;}
  public Task<ZiniaoProduct> VerifyAsync(PriceCutPlan p,CancellationToken ct){Calls.Add("verify");return Task.FromResult(Current);}
  public Task CloseAsync()=>Task.CompletedTask;
 }
 static Task<ExecutionResult> Run(Client c,PriceCutPlan? previous=null,Action<PriceCutPlan>? save=null)=>new ZiniaoPriceCutExecutor(c).ExecuteAsync(Input(),p=>{c.Calls.Add("checkpoint-"+p.Stage);save?.Invoke(p);},default,previous,true,true);
 [Fact] public async Task LowTargetLowersBaseThenRejoinsAtTheTablePrice(){var c=new Client();var plans=new List<PriceCutPlan>();var r=await Run(c,save:plans.Add);Assert.Equal(RowStatus.Succeeded,r.Status);Assert.Equal(18.9m,r.Observation!.CurrentPrice);Assert.Equal(75.6m,ZiniaoReadOnlyExecutor.Money(c.Current.BasePriceText));Assert.Equal(new[]{"discount-exit","discount-base","discount-join"},plans.Select(p=>p.Stage));Assert.All(plans,p=>Assert.Equal(18.9m,p.Input.TargetPrice));Assert.True(c.Calls.IndexOf("save-base")<c.Calls.IndexOf("join"));}
 [Fact] public async Task TargetAlreadyMatchedStillCorrectsExcessiveDiscount(){var c=new Client{Current=Product(price:18.9m)};Assert.Equal(RowStatus.Succeeded,(await Run(c)).Status);Assert.Contains("save-base",c.Calls);Assert.Equal(75.6m,ZiniaoReadOnlyExecutor.Money(c.Current.BasePriceText));}
 [Fact] public async Task SharedSiblingConflictBlocksEvenWhenCurrentPriceMatchesTarget(){var c=new Client{Current=Product(price:18.9m) with{SharedSkus=["SKU-A","SKU-B"]}};var input=Input();var r=await new ZiniaoPriceCutExecutor(c).ExecuteAsync(input,_=>{},default,null,true,true,[input,input with{Sku="SKU-B",TargetPrice=25}]);Assert.Equal(RowStatus.NeedsReview,r.Status);Assert.DoesNotContain("exit",c.Calls);Assert.DoesNotContain("save-base",c.Calls);}
 [Fact] public async Task ExplicitOrdinaryCampaignCannotBeReplaced(){var c=new Client{Current=Product(active:false)};var r=await new ZiniaoPriceCutExecutor(c).ExecuteAsync(Input() with{PromotionId="C-2"},_=>{},default,null,true,true);Assert.Equal(RowStatus.NeedsReview,r.Status);Assert.DoesNotContain("save-base",c.Calls);Assert.DoesNotContain("join",c.Calls);}
 [Fact] public async Task UnderReviewAfterBaseNeverJoins(){var c=new Client{UnderReviewAfterBase=true};var r=await Run(c);Assert.Equal(RowStatus.NeedsReview,r.Status);Assert.False(r.Retryable);Assert.Contains("审核未激活",r.Message);Assert.DoesNotContain("join",c.Calls);}
 [Fact] public async Task UnderReviewAfterJoinNeverReportsSuccess(){var c=new Client{UnderReviewAfterJoin=true};var r=await Run(c);Assert.Equal(RowStatus.NeedsReview,r.Status);Assert.Contains("审核未激活",r.Message);Assert.False(r.Retryable);}
 [Fact] public async Task UnknownExitNeverExitsAgain(){var c=new Client{ExitDisconnect=true};PriceCutPlan? saved=null;Assert.True((await Run(c,save:p=>saved=p)).Retryable);c.Calls.Clear();c.ExitDisconnect=false;Assert.Equal(RowStatus.Succeeded,(await Run(c,saved)).Status);Assert.DoesNotContain("exit",c.Calls);}
 [Fact] public async Task SavedBaseUnknownDoesNotSaveTwice(){var c=new Client{BaseDisconnect=true};PriceCutPlan? saved=null;Assert.True((await Run(c,save:p=>saved=p)).Retryable);Assert.Equal("discount-base",saved!.Stage);c.Calls.Clear();c.BaseDisconnect=false;Assert.Equal(RowStatus.Succeeded,(await Run(c,saved)).Status);Assert.DoesNotContain("save-base",c.Calls);Assert.DoesNotContain("exit",c.Calls);}
 [Fact] public async Task JoinedUnknownOnlyReconciles(){var c=new Client{JoinDisconnect=true};PriceCutPlan? saved=null;Assert.True((await Run(c,save:p=>saved=p)).Retryable);Assert.Equal("discount-join",saved!.Stage);c.Calls.Clear();Assert.Equal(RowStatus.Succeeded,(await Run(c,saved)).Status);Assert.DoesNotContain("join",c.Calls);Assert.DoesNotContain("save-base",c.Calls);}
 [Fact] public async Task ChangedBaseIsNeverOverwritten(){var c=new Client{ChangeBaseUnexpected=true};Assert.Equal(RowStatus.NeedsReview,(await Run(c)).Status);Assert.DoesNotContain("join",c.Calls);}
 [Fact] public async Task NoOfferAfterBaseKeepsMeaningfulReview(){var c=new Client{NoOffer=true};var r=await Run(c);Assert.Equal(RowStatus.NeedsReview,r.Status);Assert.True(r.Retryable);Assert.DoesNotContain("join",c.Calls);Assert.Contains("原价",r.Message);}
 [Fact] public async Task CheckpointFailureCannotConfirmMutation(){var c=new Client();await Run(c,save:_=>throw new IOException());Assert.DoesNotContain("exit",c.Calls);Assert.DoesNotContain("save-base",c.Calls);}
 [Fact] public async Task VerificationPropagatesAndKeepsExitCheckpoint(){var c=new Client{Verification=true};PriceCutPlan? saved=null;await Assert.ThrowsAsync<VerificationRequiredException>(()=>Run(c,save:p=>saved=p));Assert.Equal("discount-exit",saved!.Stage);Assert.DoesNotContain("save-base",c.Calls);}
 [Fact] public async Task NewWorkflowHasDurableOrderedStorageChecks(){var dir=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString());try{var s=new JobStore(dir);var v=StorageTests.Snapshot(1);v.Rows[0]=v.Rows[0] with{Input=Input()};var j=s.Create(v,ExecutionMode.PriceCut,true,true);s.TryStart(j.Summary.Id);var r=s.ClaimNext(j.Summary.Id)!;var p=new PriceCutPlan(new("123","测试","MercadoLibre-巴西"),Input(),Product(),"C-1",33.79m,169,Stage:"discount-exit",ChangeBase:true,DiscountBase:75.6m);s.SavePriceCutPlan(j.Summary.Id,r.Id,p);Assert.Throws<AppException>(()=>s.SavePriceCutPlan(j.Summary.Id,r.Id,p));var b=p with{Stage="discount-base",DiscountPromotionId="C-1"};s.SavePriceCutPlan(j.Summary.Id,r.Id,b);var join=b with{Stage="discount-join",OfferPrice=71.82m};s.SavePriceCutPlan(j.Summary.Id,r.Id,join);Assert.Throws<AppException>(()=>s.SavePriceCutPlan(j.Summary.Id,r.Id,join with{DiscountBase=80}));Assert.Throws<AppException>(()=>s.SavePriceCutPlan(j.Summary.Id,r.Id,b));Assert.Equal(75.6m,new JobStore(dir).Get(j.Summary.Id).Rows[0].PriceCut!.DiscountBase);}finally{Directory.Delete(dir,true);}}
}
